function unq(v) {
  if (typeof v !== 'string') return v;
  try { const p = JSON.parse(v); return typeof p === 'string' ? p : v; } catch { return v.replace(/^"|"$/g, ''); }
}
// Multi-series line: top 8 sub-topics over time.
const rows = $input.all().map(i => i.json);
const totals = {};
const series = {};   // subtopic -> {date: cnt}
const days = new Set();
for (const r of rows) {
  const sub = String(unq(r.subtopic) ?? 'unknown');
  const d = String(r.d).slice(0, 10);
  const cnt = Number(r.cnt || 0);
  totals[sub] = (totals[sub] || 0) + cnt;
  series[sub] = series[sub] || {};
  series[sub][d] = cnt;
  days.add(d);
}
const labels = Array.from(days).sort();
const top = Object.entries(totals).sort((a,b) => b[1]-a[1]).slice(0, 8).map(e => e[0]);
const palette = ['#4e79a7','#f28e2b','#e15759','#76b7b2','#59a14f','#edc948','#b07aa1','#ff9da7'];
const datasets = top.map((sub, i) => ({
  label: sub,
  data: labels.map(d => Number(series[sub][d] || 0)),
  borderColor: palette[i % palette.length],
  fill: false,
}));
const chartTitle = $('Set Params').first().json.chart_title;
const chartConfig = {
  type: 'line',
  data: { labels, datasets },
  options: { plugins: { title: { display: true, text: chartTitle } } }
};
return [{ json: { status: "success", content: { ...chartConfig, type: 'line' } } }];
